import com.crowdin.client.core.http.exceptions.CrowdinApiException;
import com.crowdin.client.core.http.exceptions.HttpBadRequestException;
import com.crowdin.client.core.http.exceptions.HttpException;
import com.crowdin.client.projectsgroups.model.Project;
import com.crowdin.client.stringtranslations.model.LanguageTranslations;
import org.junit.Assert;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

public class JacksonJsonTransformerTest {

    // The instance of class under test
    JacksonJsonTransformer transformer = new JacksonJsonTransformer();

    @Test
    public void ParseHttpExceptionClassTest() throws Exception {
        String json = "{\"message\":\"Bad Request\",\"statusCode\":400}";
        HttpException actual = transformer.parse(json, HttpException.class);
        assertNotNull(actual);
        assertEquals("Bad Request", actual.getMessage());
        assertEquals(400, actual.getStatusCode());
    }

    @Test(expected = CrowdinApiException.class)
    public void parseCrowdinApiExceptionClassTest() throws Exception {
        String json = "{\"errorCode\":\"404\",\"message\":\"Not Found\"}";
        transformer.parse(json, CrowdinApiException.class);
    }

    @Test
    public void parseHttpBadRequestExceptionClassTest() throws Exception {
        String json = "{\"message\":\"Bad Request\",\"statusCode\":400}";
        HttpBadRequestException actual = transformer.parse(json, HttpBadRequestException.class);
        assertNotNull(actual);
        assertEquals("Bad Request", actual.getMessage());
        assertEquals(400, actual.getStatusCode());
    }

    @Test
    public void parseProjectClassTest() throws Exception {
        String json = "{\"id\":1,\"name\":\"Test Project\"}";
        Project actual = transformer.parse(json, Project.class);
        assertNotNull(actual);
        assertEquals(1, actual.getId());
        assertEquals("Test Project", actual.getName());
    }

    @Test
    public void parseLanguageTranslationsClassTest() throws Exception {
        String json = "{\"languageId\":\"fr\",\"stringsCount\":15}";
        LanguageTranslations actual = transformer.parse(json, LanguageTranslations.class);
        assertNotNull(actual);
        assertEquals("fr", actual.getLanguageId());
        assertEquals(15, actual.getStringsCount());
    }

    @Test
    public void convertObjectToJsonTest() throws Exception {
        LanguageTranslations langTranslation = new LanguageTranslations();
        langTranslation.setLanguageId("fr");
        langTranslation.setStringsCount(15);

        String actualJson = transformer.convert(langTranslation);
        String expectedJson = "{\"languageId\":\"fr\",\"stringsCount\":15}";
        Assert.assertEquals(actualJson, expectedJson);
    }
}
